    std::vector<int > V;
    std::vector<int > E;
    std::vector<int > F;
    FaceMesh M;
    std::vector<Eigen::Matrix<double, 3, 1>> x;
    Eigen::Matrix<double, 3, 1> VertexNormal(
        const int & i)
    {
