                // `cot(β)` = cot(p, i, j)
            double cotβ = cot(p, i, j);
            sum_2 += (cotα + cotβ) * (this->x.at(i) - this->x.at(j));
        }
        return double(1 / double(2)) * (sum_2);    
    }
    struct Neighborhoods {
