\mathit{HN}\left( i \right) & = \frac{1}{2} \left( \sum_{j\in \mathit{VertexOneRing}\left( i \right)} \left( cot(α) + cot(β) \right) \left( x_{ i } - x_{ j } \right) \qquad \text{{ where }}  k,p = \mathit{OppositeVertices}\left( i,j \right), cot(α) = \mathit{cot}\left( k,j,i \right), cot(β) = \mathit{cot}\left( p,i,j \right) \right) \text{{ where }}  i ∈ V \\
\end{align*}
\end{minipage}
}
\end{center}

