            f = FaceIndex(i, j, k);
            tuple_7 = NeighborVerticesInFace(f, i);
            ret_22 = tuple_7(1);
            ret_23 = tuple_7(2);
        end
        output.V = V;
        output.E = E;
        output.F = F;
        output.dee0 = dee0;
        output.dee1 = dee1;
        output.B0 = B0;
        output.B1 = B1;
        output.B0T = B0T;
        output.B1T = B1T;
        output.VertexOneRing = @VertexOneRing;
        output.VertexOneRing_0 = @VertexOneRing_0;
        output.EdgeIndex = @EdgeIndex;
        output.NeighborVerticesInFace = @NeighborVerticesInFace;
        output.NextVerticeInFace = @NextVerticeInFace;
        output.OrientedVertices = @OrientedVertices;
        output.Diamond = @Diamond;
        output.OrientedOppositeFaces = @OrientedOppositeFaces;
        output.OppositeFaces = @OppositeFaces;
        output.OppositeVertices = @OppositeVertices;
        output.OppositeVertices_0 = @OppositeVertices_0;
        output.FaceIndex = @FaceIndex;
        output.OrientedVertices_0 = @OrientedVertices_0;
        output.M = M;
    end
    Neighborhoods_ = Neighborhoods(M);
    Faces = @Neighborhoods_.Faces;
    Faces_0 = @Neighborhoods_.Faces_0;
    Faces_1 = @Neighborhoods_.Faces_1;
    VertexOneRing = @Neighborhoods_.VertexOneRing;
    VertexOneRing_0 = @Neighborhoods_.VertexOneRing_0;
    OrientedOppositeFaces = Neighborhoods_.OrientedOppositeFaces;
    OppositeVertices = @Neighborhoods_.OppositeVertices;
    OppositeVertices_0 = @Neighborhoods_.OppositeVertices_0;
    NeighborVerticesInFace = Neighborhoods_.NeighborVerticesInFace;
    OrientedVertices = @Neighborhoods_.OrientedVertices;
    OrientedVertices_0 = @Neighborhoods_.OrientedVertices_0;
    function [ret] = VertexNormal(i)
        assert(numel(i) == 1);
        assert( ismember(i, V) );

        sum_0 = zeros(3,1);
        range = Faces_0(i);
        for index = 1:length(range)
            f = range(index);
                [j, k] = NeighborVerticesInFace(f, i);
            sum_0 = sum_0 + cross((x(j,:)' - x(i,:)'), (x(k,:)' - x(i,:)')) / (norm(x(j,:)' - x(i,:)', 2).^2 * norm(x(k,:)' - x(i,:)', 2).^2);
        end
        ret = (sum_0);
    end

    function [ret_1] = theta(i, f)
        assert(numel(i) == 1);
        assert(numel(f) == 1);
        assert( ismember(i, V) );
        assert( ismember(f, F) );

        [j, k] = NeighborVerticesInFace(f, i);
        ret_1 = acos(dot((x(j,:)' - x(i,:)'),(x(k,:)' - x(i,:)')) / (norm(x(j,:)' - x(i,:)', 2) * norm(x(k,:)' - x(i,:)', 2)));
    end

    function [ret_2] = area(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        [i, j, k] = OrientedVertices(f);
        ret_2 = (1/2) * norm(cross((x(j,:)' - x(i,:)'), (x(k,:)' - x(i,:)')), 2);
    end

    function [ret_3] = N(f)
        assert(numel(f) == 1);
        assert( ismember(f, F) );

        [i, j, k] = OrientedVertices(f);
        ret_3 = (cross((x(j,:)' - x(i,:)'), (x(k,:)' - x(i,:)'))) / (2 * area(f));
    end

    function [ret_4] = l(i, j)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );

        ret_4 = norm(x(j,:)' - x(i,:)', 2);
    end

    function [ret_5] = phi(i, j)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );

        % e = (x_j-x_i)/‖x_j-x_i‖
        e = (x(j,:)' - x(i,:)') / norm(x(j,:)' - x(i,:)', 2);

        [f_1, f_2] = OrientedOppositeFaces(i, j);

        % `n_1` = N(`f_1`)
        n_1 = N(f_1);

        % `n_2` = N(`f_2`)
        n_2 = N(f_2);
        ret_5 = atan2(dot(e,(cross(n_1, n_2))), dot(n_1,n_2));
    end

    function [ret_6] = cot(k, j, i)
        assert(numel(k) == 1);
        assert(numel(j) == 1);
        assert(numel(i) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );
        assert( ismember(k, V) );

        [oj, oi] = OrientedVertices_0(k, j, i);

        % cos = (x_oj - x_k)⋅(x_oi-x_k)
        cos = dot((x(oj,:)' - x(k,:)'),(x(oi,:)' - x(k,:)'));

        % sin = ‖(x_oj - x_k)×(x_oi-x_k)‖
        sin = norm(cross((x(oj,:)' - x(k,:)'), (x(oi,:)' - x(k,:)')), 2);
        ret_6 = cos / sin;
    end

    function [ret_7] = KN(i)
        assert(numel(i) == 1);
        assert( ismember(i, V) );

        sum_1 = zeros(3,1);
        range_1 = VertexOneRing(i);
        for index_1 = 1:length(range_1)
            j = range_1(index_1);
            sum_1 = sum_1 + phi(i, j) / l(i, j) * (x(j,:)' - x(i,:)');
        end
        ret_7 = 1 / 2 * (sum_1);
    end

    function [ret_8] = HN(i)
        assert(numel(i) == 1);
        assert( ismember(i, V) );

        sum_2 = zeros(3,1);
        range_2 = VertexOneRing(i);
        for index_2 = 1:length(range_2)
            j = range_2(index_2);
                [k, p] = OppositeVertices_0(i, j);
                % `cot(α)` = cot(k, j, i)
            cotalpha = cot(k, j, i);
                % `cot(β)` = cot(p, i, j)
            cotbeta = cot(p, i, j);
            sum_2 = sum_2 + (cotalpha + cotbeta) * (x(i,:)' - x(j,:)');
        end
        ret_8 = 1 / 2 * (sum_2);
    end

    output.V = V;
    output.E = E;
    output.F = F;
    output.VertexNormal = @VertexNormal;
    output.theta = @theta;
    output.area = @area;
    output.N = @N;
    output.l = @l;
    output.phi = @phi;
    output.cot = @cot;
    output.KN = @KN;
    output.HN = @HN;
    output.M = M;    
    output.x = x;
end
